script:
deploy = json.decode(repo.read("deploy.json"))
overrides_raw = repo.read("overrides.json", missing_ok=True)

prod = []
for t in deploy.get("targets", []):
    if t.get("env") == "prod":
        prod.append(t)

names = sorted([t.get("name") for t in prod])
total = 0
for t in prod:
    total += t.get("replicas", 0)

overrides = {}
if overrides_raw != None:
    overrides = json.decode(overrides_raw)

result({
  "prod_targets": prod,
  "sorted_names": names,
  "total_replicas": total,
  "overrides_present": overrides_raw != None,
  "overrides": overrides,
  "status": repo.status(),
})
